tool_and_message_events.command:
/bin/bash -lc "node - <<'NODE'
const fs = require('node:fs');
const archive = fs.readFileSync('distribution/shift.asar');
const headerSize = archive.readUInt32LE(4);
const manifestSize = archive.readUInt32LE(12);
const manifest = JSON.parse(archive.subarray(16, 16 + manifestSize));
for (const [name, entry] of Object.entries(manifest.files)) {
  if (entry.offset === undefined || entry.size === undefined) {
    console.log(name, Object.keys(entry));
    continue;
  }
  const start = 8 + headerSize + Number(entry.offset);
  const bytes = archive.subarray(start, start + entry.size);
  const local = "'`distribution/${name}`;
  console.log(name, bytes.length, fs.existsSync(local) ? `matches loose file: ${bytes.equals(fs.readFileSync(local))}` : '"'archive only');
  if (name === 'index.html') console.log(bytes.toString());
}
NODE"

